const fs = require('fs');
const products = JSON.parse(fs.readFileSync('scripts/extracted-products.json', 'utf8'));
function stripHtml(html) {
  return html
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<[^>]+>/g, ' ')
