    .replace(/\r\n/g, '\n')
    .replace(/\n{2,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}
const ext = (dir, slug) => {
  const files = fs.readdirSync(dir);
