  image: \`/products/\${p.slug}.\${ext('public/products', p.slug)}\`,
  panorama: \`/panoramas/\${p.slug}.\${ext('public/panoramas', p.slug)}\`,
}));
fs.writeFileSync('scripts/products-clean.json', JSON.stringify(out, null, 2));
console.log('OK', out.length);
"

