{
  "name": "pano360",
  "type": "module",
  "version": "0.0.1",
  "scripts": {
    "dev": "astro dev",
    "build": "astro build",
    "preview": "astro preview",
    "astro": "astro"
  },
  "dependencies": {
    "astro": "^6.1.1"
  },
  "devDependencies": {
    "@types/node": "^25.4.0"
  }
}

// @ts-check
import { defineConfig } from 'astro/config';

// https://astro.build/config
export default defineConfig({
	site: 'https://pano360.soloquedalopeor.com',
	base: '/',
});

{
  "extends": "astro/tsconfigs/strict",
  "compilerOptions": {
    "types": ["node", "astro/client"]
  },
  "include": [".astro/types.d.ts", "**/*"],
  "exclude": ["dist"]
}

---
export interface Props {
	title: string;
	description?: string;
}
const { title, description = 'PANO360 · Fotografías esféricas 360º de SQLP' } = Astro.props as Props;
const toBasePath = (path = '') => `/${path.replace(/^\/+/, '')}`;
---
<!doctype html>
<html lang="es">
	<head>
		<meta charset="utf-8" />
		<meta name="viewport" content="width=device-width" />
		<meta name="generator" content={Astro.generator} />
		<meta name="description" content={description} />
		<title>{title}</title>
		<link rel="preconnect" href="https://fonts.googleapis.com" />
		<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
		<link
			rel="stylesheet"
			href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,700&family=Space+Grotesk:wght@400;500;600&display=swap"
		/>
	</head>
	<body>
		<header class="top">
			<a class="brand" href={toBasePath('')}>
				<span class="brand-text">PANO360</span>
			</a>
			<button class="menu-toggle" type="button" aria-label="Abrir menú" aria-controls="main-nav" aria-expanded="false">
				<span></span>
				<span></span>
				<span></span>
			</button>
			<nav class="top-nav" id="main-nav">
				<a href={toBasePath('')}>Inicio</a>
				<a href={toBasePath('catalogo')}>Catálogo</a>
			</nav>
		</header>

		<main>
			<slot />
		</main>

		<footer class="footer">
			<p>© 2026 PANO360 .:. SQLP .:. Fotografías esféricas de nuestro entorno</p>
		</footer>

		<script is:inline>
			const topHeader = document.querySelector('.top');
			const menuToggle = topHeader?.querySelector('.menu-toggle');
			const topNav = topHeader?.querySelector('.top-nav');

			if (topHeader && menuToggle && topNav) {
				topHeader.classList.add('is-menu-ready');

				const closeMenu = () => {
					topNav.classList.remove('is-open');
					menuToggle.setAttribute('aria-expanded', 'false');
					menuToggle.setAttribute('aria-label', 'Abrir menú');
				};

				menuToggle.addEventListener('click', () => {
					const isOpen = menuToggle.getAttribute('aria-expanded') === 'true';
					const shouldOpen = !isOpen;
					topNav.classList.toggle('is-open', shouldOpen);
					menuToggle.setAttribute('aria-expanded', String(shouldOpen));
					menuToggle.setAttribute('aria-label', shouldOpen ? 'Cerrar menú' : 'Abrir menú');
				});

				topNav.querySelectorAll('a').forEach((link) => {
					link.addEventListener('click', closeMenu);
				});

				window.addEventListener('resize', () => {
					if (window.innerWidth > 900) {
						closeMenu();
					}
				});
			}
		</script>

		<style is:global>
			:root {
				--bg-1: #061622;
				--bg-2: #0a2438;
				--bg-3: #0e3a3a;
				--text: #eef6f7;
				--muted: #9fb8c2;
				--accent: #4dd0e1;
				--accent-2: #ffb74d;
			}

			* { box-sizing: border-box; }

			body {
				margin: 0;
				font-family: 'Space Grotesk', sans-serif;
				color: var(--text);
				background: linear-gradient(150deg, var(--bg-2), var(--bg-1) 60%, var(--bg-3));
				min-height: 100vh;
			}

			h1, h2, h3 { font-family: 'Fraunces', serif; }

			a { color: inherit; }

			.top {
				position: sticky;
				top: 0;
				z-index: 20;
				display: flex;
				align-items: center;
				justify-content: space-between;
				padding: 1rem 1.5rem;
				background: rgba(6, 22, 34, 0.85);
				backdrop-filter: blur(6px);
				border-bottom: 1px solid rgba(255, 255, 255, 0.08);
			}

			.brand {
				text-decoration: none;
				display: flex;
				align-items: center;
				gap: 0.6rem;
			}

			.brand-text {
				font-family: 'Fraunces', serif;
				font-weight: 700;
				letter-spacing: 0.08em;
				font-size: 1.15rem;
			}

			.menu-toggle {
				display: none;
				flex-direction: column;
				gap: 5px;
				background: none;
				border: none;
				cursor: pointer;
				padding: 0.4rem;
			}

			.menu-toggle span {
				width: 22px;
				height: 2px;
				background: var(--text);
			}

			.top-nav {
				display: flex;
				gap: 1.5rem;
			}

			.top-nav a {
				text-decoration: none;
				opacity: 0.8;
				font-size: 0.95rem;
			}

			.top-nav a:hover,
			.top-nav a[aria-current='page'] {
				opacity: 1;
				color: var(--accent);
