export interface Props {
	title: string;
	description?: string;
}
const { title, description = 'PANO360 · Fotografías esféricas 360º de SQLP' } = Astro.props as Props;
const toBasePath = (path = '') => `/${path.replace(/^\/+/, '')}`;
---
<!doctype html>
